import hashlib,json,statistics,subprocess,sys
from pathlib import Path
p=Path(sys.argv[1])
cases=[('thrash',256,512,1,1,2048),('thrash',256,512,32,1,2048),('thrash',256,512,512,1,2048),('thrash',4096,8192,1,1,8192),('thrash',8,16,1,1,8192),('warm',256,256,16,1,32768),('warm',256,256,16,4,32768),('local',256,1,1,1,65536),('local',256,1,1,4,65536),('warm',255,255,15,4,32640)]
r={'timing':[],'allocation':[],'summary':[], 'binaries':{}}
for rev in ['baseline','fix']:
 for mode in ['time','alloc']:
  file=p/(rev+'-'+mode);r['binaries'][file.name]=hashlib.sha256(file.read_bytes()).hexdigest()
for case,cap,keys,styles,threads,n in cases:
 for pair in range(5):
  for rev in (['baseline','fix'] if pair%2==0 else ['fix','baseline']):
   cpus='0' if threads==1 else '0-3'
   row=json.loads(subprocess.check_output(['taskset','-c',cpus,str(p/(rev+'-time')),case,str(cap),str(keys),str(threads),str(n),'2','3',str(styles)]))
   row.update(revision=rev,pair=pair);r['timing'].append(row)
 if threads==1:
  for pair in range(3):
   for rev in (['baseline','fix'] if pair%2==0 else ['fix','baseline']):
    row=json.loads(subprocess.check_output([str(p/(rev+'-alloc')),case,str(cap),str(keys),'1',str(n),'2','3',str(styles)]))
    row.update(revision=rev,pair=pair);r['allocation'].append(row)
 row={'case':case,'cap':cap,'keys':keys,'styles':styles,'threads':threads}
 digests=set()
 for rev in ['baseline','fix']:
  time=[t for t in r['timing'] if all(t[k]==row[k] for k in ['case','cap','keys','styles','threads']) and t['revision']==rev]
  ns=[t0/(n*threads) for t in time for t0 in t['elapsed_ns']]
  assert len(ns)==15
  digests.update(t['selection_sha256'] for t in time)
  row[rev]={'median_ns_per_operation':statistics.median(ns),'min_ns_per_operation':min(ns),'max_ns_per_operation':max(ns),'matched_keys':time[0]['matched_keys']}
  alloc=[t for t in r['allocation'] if all(t[k]==row[k] for k in ['case','cap','keys','styles','threads']) and t['revision']==rev]
  if alloc:
   counts=[c for t in alloc for c in t['allocations']]
   row[rev]['allocation_per_sample']=counts[0]
   row[rev]['all_allocation_samples_equal']=all(c==counts[0] for c in counts)
   row[rev]['initial_cache_and_selection']=alloc[0]['initial_cache_and_selection']
 assert len(digests)==1
 row['selection_sha256']=next(iter(digests))
 row['time_ratio']=row['fix']['median_ns_per_operation']/row['baseline']['median_ns_per_operation']
 r['summary'].append(row)
 (p/'public-measurements.json').write_text(json.dumps(r,indent=2)+'\n')
 print(row['case'],cap,keys,styles,threads,'ratio',round(row['time_ratio'],4),'base/fix',round(row['baseline']['median_ns_per_operation'],1),round(row['fix']['median_ns_per_operation'],1),flush=True)
r['script']=Path(__file__).read_text();(p/'public-measurements.json').write_text(json.dumps(r,indent=2)+'\n')

