        "cold misses inspected {} stamps",
        PROBES.with(Cell::get)
    );
}

#[test]
fn delayed_recency_updates_preserve_lru_and_hash_replacement() {
    let mut cache = MatchCache::default();
    for key in 0..3 {
        insert(&mut cache, 3, key);
    }
    touch(&cache, 0);
    touch(&cache, 2);
    insert(&mut cache, 3, 3);
    assert!(!cache.index.contains_key(&1));
    assert!(cache.index.contains_key(&0));
    assert!(cache.index.contains_key(&2));
    // Replacing a hash changes its key and age in place, without a new slot.
    cache.insert(3, (1, None), FontQuery::default(), "collision", 2, None);
    insert(&mut cache, 3, 4);
    assert!(!cache.index.contains_key(&0));
    assert!(cache.index.contains_key(&2));
    assert!(cache.index.contains_key(&3));
    assert!(cache.index.contains_key(&4));
    assert_eq!(cache.len(), 3);
}

#[test]
fn indexed_eviction_agrees_with_scan_under_mixed_hits_and_generations() {
    for cap in [1, 2, 8, 256] {
        let mut cache = MatchCache::default();
        for key in 0..cap as u64 {
            insert(&mut cache, cap, key);
        }
        let mut random = 17u64;
        for key in cap as u64..cap as u64 + 1500 {
            random = random.wrapping_mul(6364136223846793005).wrapping_add(1);
            let slot = random as usize % cap;
            let old = cache.slots[slot].hash;
            touch(&cache, old);
            let victim = cache
                .slots
                .iter()
                .enumerate()
                .min_by_key(|(_, e)| e.used.load(Relaxed))
                .unwrap()
                .0;
            let evicted = cache.slots[victim].hash;
            insert(&mut cache, cap, key);
            assert!(!cache.index.contains_key(&evicted));
            assert_eq!(cache.index[&key] as usize, victim);
            assert_eq!(cache.len(), cap);
        }
        cache.sync((2, None));
        assert!(cache.is_empty());
        insert(&mut cache, cap, 5000);
        assert_eq!(cache.len(), 1);
        assert!(
            cache
                .get((1, None), 5000, &FontQuery::default(), *b"Zyyy", "5000")
                .is_none()
        );
    }
}

